(function () {
  var state = String(global('MRM_STATE') || '');
  var session = String(global('MRM_SESSION') || '');
  var parameter = String(typeof par1 === 'undefined' ? '' : par1);
  setGlobal('MRM_ERROR', '[DEBUG-MRM-LAUNCH] before state=' + state + ' session=' + session + ' par1=' + parameter);
}());

(function () {
  var state = String(global('MRM_STATE') || 'IDLE');
  var session = String(global('MRM_SESSION') || '');
  var parameter = String(typeof par1 === 'undefined' ? '' : par1);
  if (state === 'STARTING' && session === parameter) {
    setGlobal('MR_ASR_ACTIVE', '1');
    setGlobal('MRM_STATE', 'RECORDING');
    setGlobal('MRM_ERROR', '');
  } else {
    setGlobal('MRM_ERROR', '[DEBUG-MRM-LAUNCH] after guard-failed state=' + state + ' session=' + session + ' par1=' + parameter);
  }
}());
